select *, last_value(monthly_fee, true) over (order by start_date, id rows between unbounded preceding and current row) as last_known_monthly_fee, ntile(4) over (partition by plan order by monthly_fee, id) as monthly_fee_bucket, ntile(5) over (partition by status order by monthly_fee desc, id) as monthly_fee_bucket_2, round(monthly_fee / sum(monthly_fee) over (partition by plan, customer_id), 4) as monthly_fee_share from subscriptions;
